  scanBarcode: "Escanear código de barras",
  scannerReady: "Apunta la cámara al código de barras.",
  cameraPermissionHint: "Permite el acceso a la cámara y coloca el código dentro del marco. El acceso requiere HTTPS.",
  cameraUnavailable: "No se pudo iniciar la cámara. Comprueba el permiso y usa una conexión segura HTTPS.",
  categories: "Categorías",
  selectMultipleCategories: "Selecciona una o varias categorías.",
  presentation: "Presentación",
  individual: "Individual",
  set: "Set",
  box: "Caja",
  quantityPresentation: "{count} × {presentation}"
});
fs.writeFileSync(path, JSON.stringify(messages));
'@
node -e $script

